        treatment_protocol="【分類】病因別: (1) 敗血症関連(SRL) — 胎盤停滞、腸炎、肺炎後、(2) 内分泌関連(ERL) — EMS/PPID、(3) 支持性負重(SL) — 対側肢疾患。【初期対応(ACVIM Consensus Statement, Belknap & Black 2018)】 X線側面像で蹄骨回転・沈下を評価、Obel grade判定。原因疾患の除去・治療。【冷却療法(予防・発症期の唯一のエビデンスある介入)】 氷水浸漬(蹄・繋部まで)を48-72時間継続、van Eps & Pollitt 2004, 2014 のプロトコル — 発症前または超早期に開始すると層状組織損傷を有意に軽減。【疼痛コントロール】 フルニキシンメグルミン 1.1 mg/kg IV/PO q12-24h(短期)、またはファイロコキシブ(エクオキソル) 0.1 mg/kg PO SID(COX-2選択的、消化管安全性が高い)、強い疼痛にはガバペンチン 10-20 mg/kg PO q8-12h、またはリドカイン CRI。【蹄のサポート(装蹄師との連携必須)】 軟床厚敷料(木屑 20 cm以上)、Styrofoamパッドまたは商業的サポート(Soft Ride boots, Redden shoes, Steward clogs)、蹄踵ウェッジで深指屈腱緊張緩和。【内分泌関連(ERL)】 PPIDにはペルゴリド 2 μg/kg PO SID(プラスシド承認)、EMSには低NSC飼料(<10% 乾物中)、メトホルミン 30 mg/kg PO BID(吸収変動大)、レボチロキシン 0.1 mg/kg PO SID(体重減少促進)。新規: SGLT2阻害薬(エルツグリフロジン 0.05-0.15 mg/kg PO SID)がインスリン調節異常関連蹄葉炎に有望(Sundra et al. EVJ 2023)。【横臥時の管理】 深層褥瘡予防、他動運動、膀胱管理。【外科適応】 深指屈腱切腱術(DDFT切腱)は難治性慢性例で検討、重度の蹄骨貫通例は安楽死も考慮。【予後判定】 発症48時間のX線所見、Obel grade、原因疾患の治療反応で判定。",
