        treatment_protocol="【初期評価】バイタル、PCV/TP、乳酸、電解質、BUN/Cre、腹水穿刺、糞便培養(Salmonella選択培地)・PCR(C.diff A/B毒素・PHF)・虫卵検査。SalmonellaはPCRより連続培養5日間が感度高。【大量輸液療法(最優先)】乳酸リンゲル液 10-20 mL/kg/hr IV × 初期、その後維持 4-6 mL/kg/hr(脱水度で調整)。低タンパク血症(TP<4.5)で血漿 2-10 L IVまたはヘタスターチ 5-10 mL/kg。電解質補正(K+: 20-40 mEq/L、Mg: 15 mg/kg/日、Na: 低下時緩徐補正)。【抗菌薬(原因別)】Salmonella:基本は使用回避(保菌延長リスク)、敗血症例のみセフチオフル 2.2 mg/kg IV/IM q12h。Clostridium:メトロニダゾール 15-25 mg/kg PO/IV q6-8h(経口>IV、腸管内濃度重要)。PHF:オキシテトラサイクリン 6.6 mg/kg IV q12h × 5日(早期投与で劇的奏効)。広域不明例:ペニシリン+ゲンタマイシン。【内毒素対策】フルニキシンメグルミン 0.25 mg/kg IV q6-8h(抗エンドトキシン低用量、RDCリスク軽減)、ポリミキシンB 6000 U/kg IV q8-12h(エンドトキシン中和、腎機能慎重監視)。【腸粘膜保護】活性炭+カオリン(バイオスポンジ、DTOSmectite) 1-2 lb PO q8-12h × 5日(C.diff毒素・内毒素結合、Lawler et al. JVIM 2008)。【蹄葉炎予防】発症から72時間、両前肢に氷水連続浸漬(-8℃、>72時間)、EVA Consortium推奨。DMSO 0.1-1 g/kg IV 3回まで(自由基除去)。【プロバイオティクス】Saccharomyces boulardii 25 g PO q12h × 1週(C.diff再発予防)。【栄養】急性期は経鼻胃管からの強制給餌回避。3-5日で食欲回復した時点から少量粗飼料。腸管粘膜修復にL-グルタミン・ω-3補給を補助的に。【再発予防】抗菌薬中止、飼養管理・ストレス軽減、CPパウダー等のプレ/プロバイオティクス補給で腸内細菌叢再建(Landes JEVS 2008/2020)。",
