        treatment_protocol="【診断】直腸検査で骨盤曲の硬便塊を触知、経鼻胃管で胃減圧と逆流確認、CBC/生化学で脱水評価。【疼痛コントロール(第一選択)】フルニキシンメグルミン 1.1 mg/kg IV q12h(BEVA 2020 Analgesia Guidelines)。強い疼痛にはデトミジン 10-20 μg/kg IV + ブトルファノール 0.02-0.04 mg/kg IV。【腸管内水分補給(治療の主軸)】経鼻胃管で流動パラフィン(ミネラルオイル) 2-4 L を2-6時間毎、温水 4-6 L q4-6h、電解質輸液経口投与、マグネシウム硫酸塩 1 g/kg 経鼻投与(1回のみ、連用しない)。【IV輸液】乳酸リンゲル液 4-8 mL/kg/hr IV(脱水補正時は維持量の2-3倍)、経口水分療法との併用が有効。【鎮痙薬補助】痙攣性要素が強い場合、ブチルスコポラミン 0.3 mg/kg IV(Roelvink 1991)。【外科適応】48-72時間内科療法無効、持続する重度疼痛、腹水異常は開腹術。通常85-95%は内科的に解消する(Merck Manual)。【再発予防】粗飼料の段階的切替、十分な飲水、歯科ケア、駆虫。",
