        merck_url=_MERCK + "enterolithiasis+horses",
        treatment_protocol="【診断】腹部X線(左右側面像、200-300kV透過):結腸内に明瞭な石灰化陰影、骨盤曲・横行結腸・小結腸に多い。腹部超音波で結石と二次的結腸壁肥厚・ガス貯留確認。直腸検査で小結腸の硬便・拡張ループ触知。【保存的排出は通常困難】結石<5cmで骨盤曲通過例を除き外科適応。【外科治療(第一選択)】開腹術による腸切開(pelvic flexure enterotomy、大結腸開存箇所)で結石摘出(Hassel et al. JAVMA 1999、治癒率>90%)。多発結石例(35-40%)では全結腸を体系的に触診。【周術期管理】術前:フルニキシン 1.1 mg/kg IV q12h、セフチオフル 2.2 mg/kg IV q12h + ゲンタマイシン 6.6 mg/kg IV SID。術後:乳酸リンゲル液 2-4 mL/kg/hr、段階的再給餌(24-48時間後から湿潤マッシュ → 徐々に乾草)。【結腸破裂・腹膜炎合併例】予後極めて不良、腹腔洗浄・広域抗菌薬(セフチオフル+メトロニダゾール 15 mg/kg PO q8h)。【再発予防(重要)】アルファルファ制限(<50%粗飼料)・イネ科牧草中心へ変更、Mg/P制限、十分な新鮮水(電解質添加で飲水促進)、pH低下目的で酢 60-120 mL PO SIDを検討(Hassel EVJ 2008)、年1回腹部X線フォロー。参考:Hassel DM et al. Enterolithiasis review. EVE 2017;Hassel et al. JAVMA 1999;215:1627。",
        clinical_signs_detail="反復性の軽度~中等度疝痛(排便後に軽快するパターン)、間欠的な糞便量減少、小結腸通過時の急性の激しい疝痛(骨盤曲で嵌頓)、腹部膨満、頻脈、直腸検査で小結腸拡張・硬便触知。カリフォルニア・南西部米国・アラビア種では生涯リスク高い。無症状で偶発的X線発見例もある",
