        merck_url=_MERCK + "inflammatory+bowel+disease+horses",
        treatment_protocol="【診断】血清総蛋白 <6.0 g/dL、アルブミン <2.5 g/dL、蛋白漏出性腸症(PLE)のパターン。糞便 α1-プロテアーゼ阻害薬(PLE指標)、腹部超音波で空腸・回腸壁肥厚(>3mm)。【確定診断】直腸生検(粘膜下層評価含める)または回盲部/空腸生検(開腹・内視鏡)。組織型:リンパ球形質細胞性腸炎(LPE、最多)、好酸球性腸炎(EE)、肉芽腫性腸炎(GE)、多巣性好酸球性上皮栄養障害(MEED)、アミロイドーシス。糖吸収試験(D-キシロース吸収低下で小腸機能低下)。【免疫抑制療法(第一選択、組織型を問わず開始可)】デキサメタゾン 0.05-0.1 mg/kg PO/IV SID × 2-3週間、症状改善に応じて q48h → q72h へ減量、プレドニゾロン 1-2 mg/kg PO SID へ切り替え3-6ヶ月。蹄葉炎リスク評価(肥満・EMS・PPIDは慎重)、PPID合併ならペルゴリド追加。【代替免疫抑制薬】アザチオプリン 3 mg/kg PO SID(ステロイド不応・副作用例、Davis et al. EVJ 2003)、CBC週1モニタリング(骨髄抑制)。【好酸球性/肉芽腫性タイプ】寄生虫駆虫(イベルメクチン + モキシデクチン、Cyathostomin深部嚢胞性駆虫)、デキサメタゾン高用量。【食事療法】高品質消化性飼料、低粗繊維、分枝鎖アミノ酸補充、完全混合ペレット少量頻回、オメガ3(亜麻仁油 100 mL/日)。CPパウダー(サイリウム+プレ/プロバイオティクス配合)は慢性IBDの腸内細菌叢補助療法として考慮可(Respondek et al. JEVS 2008のプレバイオティクスエビデンス、慢性下痢改善報告)。【低アルブミン血症対策】血漿輸血 2-6 L(<2.0 g/dL)、ヘタスターチ 5-10 mL/kg IV、ラシックス使用は低アルブミン血症下で慎重。【予後】LPE中等度で寛解率50-60%、GE/MEED/アミロイドーシスは予後不良。参考:Schumacher J et al. IBD in horses. JVIM 2000;14:258-265;Kalck KA. Inflammatory bowel disease in horses. VCNA Equine Pract 2009;25:303。",
        clinical_signs_detail="慢性的な進行性体重減少(食欲正常にもかかわらず)、慢性軟便・水様性下痢(LPE型は正常便のこともある)、低アルブミン血症による下腹部浮腫・胸水・腹水、被毛粗剛、反復性軽度疝痛、活動性低下。急性悪化で重度下痢・ショック。直腸検査でうっ血性腸間膜リンパ節腫大(GE型)",
