        merck_url=_MERCK + "phytobezoar+enterolith+horses",
        treatment_protocol="【診断】直腸検査で小結腸・骨盤入口部に硬い異物様腫瘤触知、X線(子馬・小型馬)またはエコーで結腸内高エコー異物確認、腹水は通常正常(壊死進行で血性)。【内科療法(軽度・近位)】絶食24-48時間、IV輸液 乳酸リンゲル液 4-6 mL/kg/hr、流動パラフィン 2-4 L 経鼻胃管 BID(潤滑・軟化)、DSS(ドキュセート) 10-20 mg/kg 経鼻胃管(界面活性、タンニンなしの繊維塊に特に有効)、マグネシウム硫酸塩 1 g/kg PO 1回(浸透圧下剤)。温水浣腸(小結腸閉塞のみ)。【疼痛管理】フルニキシンメグルミン 1.1 mg/kg IV q12h、ブトルファノール 0.02-0.04 mg/kg IV、ブチルスコポラミン 0.3 mg/kg IV(痙攣性要素)。【外科適応】48時間内科不応、完全閉塞、虚血徴候(頻脈>60、乳酸>4)で開腹術。小結腸では腸切開より経肛門拡張除去が低侵襲。近位結腸例では盲腸底・pelvic flexureからアプローチ。【術後】広域抗菌薬(ペニシリン+ゲンタマイシン×5日)、12-24時間NPO後に少量流動食、1週間かけて通常飼料へ。【再発予防(最重要)】歯科検診(鋭い歯冠補正)、十分飲水(冬季加温水)、粗飼料は短く刈る(<5cm)、高齢馬への粗悪藁給与回避、サイリウム維持投与(月1週間)。",
        clinical_signs_detail="慢性的・反復性の軽度疝痛、排便量減少または停止、排便時努責、腹部膨満(部分閉塞)、完全閉塞では頻脈・発汗・急性疝痛、小結腸閉塞では直腸検査で腫瘤触知、二次性胃逆流は末期所見",
        risk_factors="高齢馬(歯科疾患多発)、粗悪な粗飼料(茎の長い藁・刈草)、飲水不足(冬季凍結水源)、運動不足、既往便秘歴、ポニー・ミニチュアホース(小結腸径小で閉塞起こしやすい)、砂地放牧(砂との複合)、刈り残しの長い牧草アクセス",
        prognosis="内科療法成功例は予後良好、外科除去例も適切管理で70-85%生存。小結腸虚血進行例・穿孔例は予後不良。再発リスクあり飼養管理継続必須",
        prevention="定期的歯科検診(6ヶ月毎)、清潔で十分な飲水確保、粗飼料の適切な長さ管理、サイリウム予防投与、砂地管理、高齢馬の個別給餌管理",
