        treatment_protocol="【診断】除外診断(Salmonella・C.difficile・PHF・右背側結腸炎を全て除外)。発症早期の検査はCBC(白血球減少→数時間で増加)、乳酸>4、PCV>55、TP<4.5、代謝性アシドーシス、電解質異常。【超積極的蘇生(黄金の数時間)】高張食塩水7.2% 4 mL/kg IV急速(初期蘇生)、即座にLRS 20-30 mL/kg/hr IV維持(大口径カテーテル×2本)。血漿 6-10 L IV(コロイド+抗エンドトキシン抗体)、ヘタスターチ 10 mL/kg。【エンドトキシン対策(必須)】ポリミキシンB 6000 U/kg IV q8h(腎機能監視下)、フルニキシン 0.25 mg/kg IV q6h(低用量抗内毒素)、ペントキシフィリン 8 mg/kg PO q8h(TNF-α抑制)、DMSO 0.1 g/kg IV q12h。【腸管保護】バイオスポンジ(DTOSmectite)1-2 lb PO q6h(毒素結合)、活性炭 1-3 g/kg PO。【経験的広域抗菌薬】ペニシリン 22,000 U/kg IV q6h + ゲンタマイシン 6.6 mg/kg IV q24h、メトロニダゾール 25 mg/kg PO/IV q8h(C.diff合併疑い)。【血管作動薬】平均動脈圧<60 mmHgでノルエピネフリン 0.1-1 μg/kg/min CRI。【蹄葉炎予防】両前肢氷水連続浸漬 >72時間。【ICU】30分毎バイタル、心電図、CVP、尿量、乳酸傾向。乳酸低下で応答評価。【予後不良因子】発症時PCV>65、乳酸>8、K+<2.5、難治性低血圧、尿量<0.5 mL/kg/hr。【生存例の長期管理】回復期の低タンパク血症遷延、腸管粘膜修復(CPパウダー等プレ/プロバイオティクス)、6-12ヶ月の腸管機能監視。",
        clinical_signs_detail="急性発症(数分-数時間):激しい腹痛・虚脱・沈鬱、プロフュース水様下痢(発症後直ぐ)、頻脈>100、粘膜暗赤~紫、CRT>6秒、末梢冷汗、発熱(40-41℃)または低体温(ショック進行)、速やかな意識障害・起立不能",
        risk_factors="急性重度ストレス(運送長距離・外科手術・分娩・競走)、高炭水化物飼料(穀類急増)、抗菌薬投与歴(セフチオフル・TMPS等)、NSAIDs併用、若齢・高齢馬、先天的腸内細菌叢脆弱性、診断時に明確な感染原因を同定できない場合",
        prognosis="生存率<20%、発症24時間以内の積極治療で30-40%まで改善可能。ショック進行後・蹄葉炎併発は予後不良",
