        "激しい運動後の肺出血。競走馬に極めて多い。",
        ["resp_epistaxis", "resp_exercise_intolerance", "resp_cough_at_exercise"],
        urgency="routine",
        recommended_exams=[(1, "内視鏡検査", "Endoscopy"), (2, "気管支肺胞洗浄液", "BAL")],
        merck_url=_MERCK + "exercise+induced+pulmonary+hemorrhage+horses",
        treatment_protocol="環境管理：粉塵の低減、換気改善、乾草の浸水・スチーム処理。気管支拡張薬(クレンブテロール 0.8 μg/kg PO BIDまたは吸入アルブテロール)で気道閉塞に対応。コルチコステロイド(デキサメタゾン 0.04-0.1 mg/kg IV/IMまたは吸入フルチカゾン/ベクロメタゾン)。細菌性肺炎には培養感受性試験に基づく抗菌薬(ST合剤、ペニシリン、ゲンタマイシン)。ウイルス性呼吸器疾患には抗ウイルス薬は通常使用不可、支持療法。生理食塩水±粘液溶解薬のネブライゼーション。上気道緊急時には気管切開。呼吸器疾患の活動期は運動を中止。",
        clinical_signs_detail="鼻汁(漿液性/粘液膿性)、咳嗽、呼吸困難・努力性呼吸、鼻翼呼吸、腹式呼吸(ヒーブライン)、運動不耐性、喘鳴・異常呼吸音、発熱、頸部リンパ節腫脹",
        risk_factors="密集飼育・換気不良、埃っぽい飼料・敷料、輸送ストレス、混合飼育(異なる施設の馬の接触)、ワクチン未接種、免疫低下(幼齢/高齢/ストレス)",
