        "披裂軟骨の炎症・変形。呼吸困難と嚥下困難。",
        ["resp_stridor", "resp_labored_breathing", "resp_nasal_discharge"],
        urgency="urgent",
        recommended_exams=[(1, "内視鏡検査", "Endoscopy"), (2, "X線検査", "Radiography"), (3, "CT検査", "CT Scan")],
        merck_url=_MERCK + "arytenoid+chondritis+horses",
        treatment_protocol="【病態】披裂軟骨炎 — 進行例・両側性・外科的救済の視点。Grade III-IV(Smith分類、披裂軟骨変形・吸気時崩壊・両側性)は抗菌薬不応で外科適応。保存療法は早期(Grade I-II)でのみ有効(rp_arytenoidエントリー参照)。本エントリーは手術適応・術式・両側病変管理に焦点。【手術前評価】(1)CT(必須):軟骨内膿瘍範囲、壊死程度、対側病変の有無、気管内腔計測を精密評価。(2)動的内視鏡:運動時気道狭窄の機能的評価。(3)術前培養:軟骨表面 + 膿瘍吸引、感受性試験に基づく周術期抗菌薬選択(Streptococcus zooepidemicus最多、Actinobacillus、Pseudomonas、Staph混合感染多い)。(4)胸部X線:誤嚥性肺炎合併評価。【術前管理】全身抗菌薬:TMS 30 mg/kg PO q12h × 術前2週、または感受性に基づく選択。NSAIDs:フェニルブタゾン 2.2 mg/kg PO q12h。ステロイドは術直前中止(創傷治癒阻害)。【手術術式】片側部分披裂軟骨切除術(Partial/Subtotal Arytenoidectomy、Tulleners 1988/1996):(1)麻酔導入後気管切開(永久的 or 一時的)、(2)頸腹側切開・甲状軟骨正中切開で喉頭露出、(3)病変披裂軟骨の体部切除(尖端・前端は可能な限り温存して声帯機能維持)、(4)粘膜弁(lateral or subepiglottic mucosal flap)で創部被覆、(5)層閉鎖、気管切開チューブ留置3-5日 → 抜去 → 2期再縫合。合併症:誤嚥・慢性咳嗽(20-30%、 Cornell collar・低位置給餌で管理)、創感染、残存気道狭窄、音声変化。【両側性病変の管理】両側partial arytenoidectomyは気道確保不能のリスク高、一般的には:(1)重症側のみ片側切除 → 軽症側は抗菌薬長期、(2)両側重度なら永久的気管切開(tracheostomy)で姑息的救命 + leisure馬対応、(3)予後極めて限定的なら安楽死。【術後ケア】抗菌薬(TMS・エンロフロキサシン)4-6週、フルニキシン 1.1 mg/kg q12h × 2週、飼料・水は低位置給与(誤嚥予防、生涯)、Cornell collar装着運動時、4週毎内視鏡フォロー6ヶ月。【予後】片側partial arytenoidectomy:leisure馬80%復帰、レース馬30%以下の競走能力回復(Smith 2010で24%再発)。両側重度:気管切開生涯姑息 or 安楽死。【参考文献】Tulleners EP. Partial arytenoidectomy. AAEP Proc 1988 / Smith JJ et al. Long-term outcome of partial arytenoidectomy in horses. EVJ 2010 / Barnes HG et al. Outcome of arytenoidectomy. AJVR 2004 / Hawkins JF. Arytenoidectomy techniques. Equine Surgery (Auer/Stick 5th ed)。",
        clinical_signs_detail="高グレード披裂軟骨炎:重度吸気性stridor(安静時も聞こえる)、運動時呼吸困難・collapse、湿性咳嗽、嚥下時の飼料漏出・液体吐出、慢性体重減少、頚部触診で披裂部腫大・圧痛。内視鏡で披裂軟骨軸面の大型肉芽腫・潰瘍・硬化性変形・粘膜下膿瘍、吸気時に軟骨体部内方崩壊、Grade IVは両側性で気道70%狭窄",
        risk_factors="Grade III-IV進行例、早期診断・治療を受けなかった慢性化症例、両側性病変、高齢馬、過去の部分切除術後再発例、複数回の抗菌薬治療後不応例、Thoroughbred・Standardbred競技馬、過去のS. equi感染既往、長期免疫抑制状態、混合細菌感染(Pseudomonas等難治性起炎菌)",
