        merck_url=_MERCK + "severe+hemorrhagic+gastric+ulcer+horses",
        treatment_protocol="【診断基準】胃内視鏡でECEIMグレード3(大きい/多発潰瘍)またはグレード4(深部潰瘍、活動性出血、フィブリン凝血付着)を確認。慢性貧血(PCV<30%)、低蛋白血症(総蛋白<5.5 g/dL)、糞便潜血陽性が多い。【高用量治療】オメプラゾール 4 mg/kg PO SID × 最低4-6週間(軽度例の28日より延長)、空腹時投与を厳守。治療前48時間の胃内視鏡再確認後、再発・未治癒なら延長。【併用療法】スクラルファート 20 mg/kg PO q6-8h × 最低4週間(粘膜被覆・ペプシン阻害、出血部位の保護)、空腹時・他薬と2時間間隔。【注射用酸分泌抑制】重症・経口困難例ではパントプラゾール 1.5 mg/kg IV SID(プロトンポンプ阻害薬、より速効性)、またはエソメプラゾール 0.5 mg/kg IV SID。【出血管理】活動性出血・重度貧血(PCV<20%)ではトラネキサム酸 10 mg/kg IV slow q8h、輸血(新鮮全血 10-20 mL/kg)。鉄剤補充(鉄デキストラン 5 mg/kg IM q7d)。【合併症管理】穿孔疑い(急性ショック・腹膜炎徴候)では緊急開腹術。治癒時の瘢痕性幽門狭窄は幽門形成術適応。【飼養管理(極めて重要)】完全休養1-2週間、24時間牧草、アルファルファペレット 1-2 kg/日、穀類完全中止、1日8-12回分割給餌、ストレス源完全除去(新環境・輸送回避)。【治癒評価】4週後再内視鏡、グレード2以下になるまで高用量治療継続。完全治癒後はオメプラゾール 1-2 mg/kg PO SID × 4-8週間の維持、その後漸減。【再発予防】グレード3-4経験馬は高リスク、永続的な飼養管理+間欠的内視鏡サーベイランス(6ヶ月毎)+ストレスイベント時の予防投与必須。",
        clinical_signs_detail="顕著な体重減少(>5%)、被毛粗剛・艶消失、慢性貧血による運動能力著減、易疲労、粘膜蒼白、慢性反復疝痛、食欲著減(特に穀類拒否)、歯ぎしり持続、時に吐血または黒色便(進行出血例)、心拍数軽度上昇、競走馬では成績著しい低下。軽度ESGDとは異なり標準治療後も症状残存することが多い",
        risk_factors="長期未治療ESGD(>3ヶ月)、反復性罹患歴、競走馬のトレーニング継続(治療中も)、複数NSAIDs併用歴、併発疾患(敗血症・重度呼吸器疾患・全身炎症)、長期絶食(手術後・運搬中)、既往の胃内視鏡でのグレード2未治療、オメプラゾール不適切使用(食後投与・低用量)、高ストレス環境(頻繁な競技・移動)",
        prognosis="適切な高用量・長期治療で60-80%が8-12週間で改善。再発率はグレード1-2より高(>50%)。穿孔例は致死率>90%。競走馬は治療中完全休養が予後を大きく改善",
        prevention="ESGD早期発見(6ヶ月毎の内視鏡スクリーニング高リスク馬)、グレード1-2段階での適切治療、NSAIDs慎重使用+胃粘膜保護薬併用、ストレスイベント時の予防投与(オメプラゾール 1-2 mg/kg PO SID × 競技期間)、適切な飼養管理の継続",
