        merck_url=_MERCK + "pyloric+ulceration+horses",
        treatment_protocol="【診断】胃内視鏡で幽門輪周囲の円形・線状の深い潰瘍・瘢痕収縮・狭窄確認。胃排出遅延の評価には13C-オクタン酸呼気試験またはシンチグラフィー。【内科療法(第一段階)】オメプラゾール 4 mg/kg PO SID × 最低8週間 + スクラルファート 12 mg/kg PO BID-TID 空腹時 × 最低8週間。ミソプロストール 5 μg/kg PO BID-TID を初期から併用(PGE1アナログで粘膜血流促進、EGGDの第一選択)。【運動性改善】エリスロマイシン 1-2 mg/kg IV/PO q6h(モチリン受容体作動薬、幽門排出促進、下痢副作用あり)、メトクロプラミド 0.04-0.05 mg/kg/hr CRI(中枢神経副作用に注意)、ベタネコール 0.025 mg/kg SC q8h。【飼養管理】少量頻回給餌(6-8回/日)、ウェットマッシュ化(水分追加で流動性改善)、穀類制限、24時間牧草アクセス、ストレス軽減(週1日完全休養)、NSAIDs中止。【治癒評価】8週後再内視鏡。改善なければ内科療法延長(さらに8-12週)またはコルチコステロイド併用(デキサメタゾン 0.05 mg/kg IV SID × 5日、漸減)。【外科適応】内科療法12-16週無効、幽門狭窄(胃排出時間>4時間)、慢性胃拡張・体重減少継続例では幽門形成術(Heineke-Mikulicz pyloroplasty)または胃十二指腸吻合術(Y-U pyloroplasty)。術後も維持療法継続。【長期管理】治癒後もスクラルファート維持 12 mg/kg PO SID、環境要因継続管理、定期内視鏡(6ヶ月毎)。【鑑別】胃腺癌(高齢馬)、扁平上皮癌、胃憩室、胃流入部狭窄も類似症状。",
        clinical_signs_detail="慢性的な軽度~中等度疝痛(食後30分-2時間、反復性)、食欲低下(特に穀類・乾草)、水分摂取増加、体重減少、経鼻胃管による少量逆流、重症例では胃拡張・持続性逆流、性格変化(敏感性・攻撃性増加)、運動能力低下、鞍敏感、歯ぎしり。慢性経過で徐々に悪化",
        risk_factors="既存EGGDの未治療・不適切治療歴(NSAIDsまたはスクラルファート単独)、長期NSAIDs使用(特にフェニルブタゾン)、慢性ストレス(過度の運動・競技スケジュール)、Warmblood・Thoroughbred品種素因、中年齢(5-15歳)、過去の胃手術歴、遺伝的素因の可能性",
